const CACHE='xiangye-v12';
const SHELL=['./','./index.html','./styles.css','./theme.css','./daily-workspace.css','./daily-workspace.js','./home-choose.css','./trip-map.css','./trip-map.js','./trip-consolidate.css','./trip-consolidate.js','./place-registry.js','./globe-places.js','./geo-service.js','./guide-data.js','./world-guides.js','./guide-ui.js','./guide-ui.css','./free-pins.js','./free-pins.css','./manual-pins.js','./manual-pins.css','./tokens.css','./globe.js','./world.geojson','./photos.js','./app.js','./design.js','./integration.js','./egypt-atlas.html','./egypt-atlas.css','./egypt-atlas.js','./egypt-guides.js','./vendor/maplibre/maplibre-gl.css','./vendor/maplibre/maplibre-gl.mjs','./vendor/maplibre/maplibre-gl-worker.mjs','./vendor/leaflet/leaflet.css','./vendor/leaflet/leaflet.js','./icon.svg','./manifest.webmanifest'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(fetch(e.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(c=>c.put(e.request,copy))}return response}).catch(()=>caches.match(e.request)))});
